insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('59814c25-d204-5bb4-b678-cae2b253eac0', 'Mutations can occur anywhere in the base sequence of a genome (although some bases mutate more often) [1]; there is no mechanism for deliberately changing a particular base to produce a beneficial trait [1].', 'Mutations can occur anywhere in the base sequence of a genome (although some bases mutate more often) [1]; there is no mechanism for deliberately changing a particular base to produce a beneficial trait [1].', '[{"text": "Marking point 1", "any": ["anywhere", "any base", "any position", "any gene"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["not deliberate", "no mechanism", "not directed", "not in response", "no purpose", "cannot choose"], "all": [], "marks": 1}]'::jsonb, 'Mutations can occur anywhere in the base sequence of a genome (although some bases mutate more often) [1]; there is no mechanism for deliberately changing a particular base to produce a beneficial trait [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
