insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('67961583-ec99-5895-a2fb-df126761f88b', 'UV radiation is a mutagen that damages DNA, causing mutations [1]; in somatic skin cells [1]; if genes controlling the cell cycle are mutated, cells divide uncontrollably, forming a tumour [1].', 'UV radiation is a mutagen that damages DNA, causing mutations [1]; in somatic skin cells [1]; if genes controlling the cell cycle are mutated, cells divide uncontrollably, forming a tumour [1].', '[{"text": "Marking point 1", "any": ["mutagen", "mutation", "damages dna"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["skin cells", "somatic"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["cell cycle", "uncontrolled", "divide", "tumour", "tumor"], "all": [], "marks": 1}]'::jsonb, 'UV radiation is a mutagen that damages DNA, causing mutations [1]; in somatic skin cells [1]; if genes controlling the cell cycle are mutated, cells divide uncontrollably, forming a tumour [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
