insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('0c777ba8-8fe4-5cef-a671-14937dc0b685', 'The gene product has essential functions, so mutations are harmful and removed by natural selection [1]; the sequence may have a slower rate of mutation [1].', 'The gene product has essential functions, so mutations are harmful and removed by natural selection [1]; the sequence may have a slower rate of mutation [1].', '[{"text": "Marking point 1", "any": ["function", "essential", "selection", "harmful", "important"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["slower", "lower rate", "less mutation", "rate of mutation"], "all": [], "marks": 1}]'::jsonb, 'The gene product has essential functions, so mutations are harmful and removed by natural selection [1]; the sequence may have a slower rate of mutation [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
