insert into public.questions (id, kind, prompt, options, marks, image_url) values ('6275119a-75e7-5042-8f7e-b848f17b63b8', 'short', 'Discuss why an international effort is being made to harmonise the regulation of gene editing.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('6275119a-75e7-5042-8f7e-b848f17b63b8', 'Scientists in different countries work under different regulations, so practices banned in one country may be done in another [1]; risks include off-target edits and heritable germ-line changes in embryos [1]; but editing has major benefits (curing genetic diseases, better crops), so shared rules allow benefits while limiting risks [1].', 'Scientists in different countries work under different regulations, so practices banned in one country may be done in another [1]; risks include off-target edits and heritable germ-line changes in embryos [1]; but editing has major benefits (curing genetic diseases, better crops), so shared rules allow benefits while limiting risks [1].', '[{"text": "Marking point 1", "any": ["different", "countries", "laws vary", "regulations vary"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["embryo", "germ line", "inherited", "designer", "unknown", "off-target", "risk"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["benefit", "treat", "cure", "disease", "food"], "all": [], "marks": 1}]'::jsonb, 'Scientists in different countries work under different regulations, so practices banned in one country may be done in another [1]; risks include off-target edits and heritable germ-line changes in embryos [1]; but editing has major benefits (curing genetic diseases, better crops), so shared rules allow benefits while limiting risks [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
