insert into public.questions (id, kind, prompt, options, marks, image_url) values ('6438aa95-0760-5281-a896-116f9f9877c5', 'short', 'Outline the epigenetic origin of the size difference between ligers and tigons.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('6438aa95-0760-5281-a896-116f9f9877c5', 'Not all epigenetic tags are removed from sperm and eggs, so some genes are imprinted according to the parent they came from [1]; in ligers the growth-limiting tags from a lioness mother are missing, so growth genes are over-expressed, while in tigons the lioness''s tags limit growth [1].', 'Not all epigenetic tags are removed from sperm and eggs, so some genes are imprinted according to the parent they came from [1]; in ligers the growth-limiting tags from a lioness mother are missing, so growth genes are over-expressed, while in tigons the lioness''s tags limit growth [1].', '[{"text": "Marking point 1", "any": ["not all", "imprint", "tags remain", "some tags"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["father", "mother", "parent", "lion", "tiger"], "all": [], "marks": 1}]'::jsonb, 'Not all epigenetic tags are removed from sperm and eggs, so some genes are imprinted according to the parent they came from [1]; in ligers the growth-limiting tags from a lioness mother are missing, so growth genes are over-expressed, while in tigons the lioness''s tags limit growth [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
