insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('bd7cba32-aea7-57fe-b955-9bdcba51145b', 'Pencil (graphite) does not dissolve in the solvent, whereas ink would separate and confuse the results [1]; if the spot were below the solvent, the pigments would dissolve into the solvent instead of moving up the paper [1].', 'Pencil (graphite) does not dissolve in the solvent, whereas ink would separate and confuse the results [1]; if the spot were below the solvent, the pigments would dissolve into the solvent instead of moving up the paper [1].', '[{"text": "Marking point 1", "any": ["ink would", "ink dissolves", "ink would run", "pencil does not"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["pigment would dissolve", "wash off", "into the solvent", "not dissolve in the solvent"], "all": [], "marks": 1}]'::jsonb, 'Pencil (graphite) does not dissolve in the solvent, whereas ink would separate and confuse the results [1]; if the spot were below the solvent, the pigments would dissolve into the solvent instead of moving up the paper [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
