insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e2a81c40-024a-51cd-9ba3-dc990c89cd67', 'Both have a similar shape [1], with peaks in the blue-violet and red parts of the spectrum and a low point in green [1]; the action spectrum is higher in the green-yellow region because accessory pigments such as carotenoids absorb some light there and pass the energy on [1].', 'Both have a similar shape [1], with peaks in the blue-violet and red parts of the spectrum and a low point in green [1]; the action spectrum is higher in the green-yellow region because accessory pigments such as carotenoids absorb some light there and pass the energy on [1].', '[{"text": "Marking point 1", "any": ["similar", "same shape", "both peak", "match"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": [], "all": ["blue", "red"], "marks": 1}, {"text": "Marking point 3", "any": ["carotenoid", "accessory"], "all": [], "marks": 1}]'::jsonb, 'Both have a similar shape [1], with peaks in the blue-violet and red parts of the spectrum and a low point in green [1]; the action spectrum is higher in the green-yellow region because accessory pigments such as carotenoids absorb some light there and pass the energy on [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
