insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('1bbf16ba-6cd6-5529-a7cc-6b33b210765b', 'As CO₂ concentration increases, the rate of photosynthesis increases until another factor becomes limiting [1], because CO₂ is a substrate fixed by Rubisco in the Calvin cycle, so more CO₂ means more is fixed per minute [1].', 'As CO₂ concentration increases, the rate of photosynthesis increases until another factor becomes limiting [1], because CO₂ is a substrate fixed by Rubisco in the Calvin cycle, so more CO₂ means more is fixed per minute [1].', '[{"text": "Marking point 1", "any": ["rate will increase", "higher rate", "faster", "rate increases"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["substrate", "rubisco", "fixed", "calvin", "raw material", "reactant", "needed to make"], "all": [], "marks": 1}]'::jsonb, 'As CO₂ concentration increases, the rate of photosynthesis increases until another factor becomes limiting [1], because CO₂ is a substrate fixed by Rubisco in the Calvin cycle, so more CO₂ means more is fixed per minute [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('dbe8f1a7-5413-5beb-afd8-aa3097a6487e', '1bbf16ba-6cd6-5529-a7cc-6b33b210765b', 15);
