insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d6929d7c-4101-5537-ae43-c7019a3e3bbf', 'Excited electrons from the photosystems pass along the electron transport chain [1]; energy released is used to pump protons into the thylakoid lumen [1]; creating a proton gradient (high concentration in the lumen) [1]; protons diffuse back into the stroma through ATP synthase, which makes ATP (chemiosmosis / photophosphorylation) [1].', 'Excited electrons from the photosystems pass along the electron transport chain [1]; energy released is used to pump protons into the thylakoid lumen [1]; creating a proton gradient (high concentration in the lumen) [1]; protons diffuse back into the stroma through ATP synthase, which makes ATP (chemiosmosis / photophosphorylation) [1].', '[{"text": "Marking point 1", "any": ["excited electron", "electrons", "electron transport chain"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["pump", "pumped"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["gradient", "high concentration", "lumen"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["atp synthase", "chemiosmosis", "flow back"], "all": [], "marks": 1}]'::jsonb, 'Excited electrons from the photosystems pass along the electron transport chain [1]; energy released is used to pump protons into the thylakoid lumen [1]; creating a proton gradient (high concentration in the lumen) [1]; protons diffuse back into the stroma through ATP synthase, which makes ATP (chemiosmosis / photophosphorylation) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('dbe8f1a7-5413-5beb-afd8-aa3097a6487e', 'd6929d7c-4101-5537-ae43-c7019a3e3bbf', 22);
