insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e6655fc6-59c4-5e9d-b249-926a7191059f', 'At high light intensity, light is no longer in short supply [1]; another factor such as CO₂ concentration or temperature becomes the limiting factor, so the rate levels off [1].', 'At high light intensity, light is no longer in short supply [1]; another factor such as CO₂ concentration or temperature becomes the limiting factor, so the rate levels off [1].', '[{"text": "Marking point 1", "any": ["another factor", "other factor", "carbon dioxide", "co2", "temperature"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["limiting", "limit"], "all": [], "marks": 1}]'::jsonb, 'At high light intensity, light is no longer in short supply [1]; another factor such as CO₂ concentration or temperature becomes the limiting factor, so the rate levels off [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
