insert into public.questions (id, kind, prompt, options, marks, image_url) values ('73798392-e0a1-5d50-a84b-ca4eca25cf67', 'short', 'Outline three properties of ATP that make it suitable as the energy currency of cells.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('73798392-e0a1-5d50-a84b-ca4eca25cf67', 'Soluble, so it moves easily to where energy is needed [1]; stable at cell pH, so it does not break down without an enzyme [1]; hydrolysis releases a suitable amount of energy for many cell tasks [1]; it is easily regenerated from ADP and phosphate [1]. (Any three.)', 'Soluble, so it moves easily to where energy is needed [1]; stable at cell pH, so it does not break down without an enzyme [1]; hydrolysis releases a suitable amount of energy for many cell tasks [1]; it is easily regenerated from ADP and phosphate [1]. (Any three.)', '[{"text": "Marking point 1", "any": ["soluble", "dissolves", "moves easily", "diffuses"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["stable", "does not break down"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["small amount", "right amount", "suitable amount", "convenient amount", "manageable"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["regenerated", "remade", "recycled", "easily made"], "all": [], "marks": 1}]'::jsonb, 'Soluble, so it moves easily to where energy is needed [1]; stable at cell pH, so it does not break down without an enzyme [1]; hydrolysis releases a suitable amount of energy for many cell tasks [1]; it is easily regenerated from ADP and phosphate [1]. (Any three.)') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0a5fa622-3d29-5fc5-973f-fbb3018dc1e9', '73798392-e0a1-5d50-a84b-ca4eca25cf67', 3);
