insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a3651167-0d53-5f2a-98fe-acc195c73bc9', 'mcq', 'Glycolysis yields per molecule of glucose:
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('a3651167-0d53-5f2a-98fe-acc195c73bc9', 2, '2 ATP used, 4 made, net 2; 2 reduced NAD; 2 pyruvate.', '2') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
