insert into public.questions (id, kind, prompt, options, marks, image_url) values ('cffa2d5b-c1b4-54cb-8f4a-7a370d22d29f', 'mcq', 'Humans, yeast or both (anaerobic respiration)?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('cffa2d5b-c1b4-54cb-8f4a-7a370d22d29f', 0, 'Glycolysis and NAD regeneration: both. Lactate: humans. Ethanol + CO₂ and bread: yeast.', 'Humans') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
