insert into public.questions (id, kind, prompt, options, marks, image_url) values ('4c607bf4-85b5-5c91-bf53-8029fd9b7db2', 'mcq', 'Humans, yeast or both (anaerobic respiration)?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('4c607bf4-85b5-5c91-bf53-8029fd9b7db2', 1, 'Glycolysis and NAD regeneration: both. Lactate: humans. Ethanol + CO₂ and bread: yeast.', 'Yeast') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0a5fa622-3d29-5fc5-973f-fbb3018dc1e9', '4c607bf4-85b5-5c91-bf53-8029fd9b7db2', 19);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('083b2d69-0161-5797-b3f8-177e0f8920e5', 'short', 'Explain why converting pyruvate to lactate allows glycolysis to continue in anaerobic conditions.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('083b2d69-0161-5797-b3f8-177e0f8920e5', 'Glycolysis needs NAD to accept hydrogen in its oxidation step [1]; in anaerobic conditions pyruvate accepts the hydrogen from reduced NAD, forming lactate [1]; this regenerates (oxidises) NAD so glycolysis can continue producing 2 ATP per glucose [1].', 'Glycolysis needs NAD to accept hydrogen in its oxidation step [1]; in anaerobic conditions pyruvate accepts the hydrogen from reduced NAD, forming lactate [1]; this regenerates (oxidises) NAD so glycolysis can continue producing 2 ATP per glucose [1].', '[{"text": "Marking point 1", "any": ["regenerate", "nad is regenerated", "nad is reformed"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["accepts hydrogen", "hydrogen to pyruvate"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["glycolysis needs nad", "oxidation step", "nad is required"], "all": [], "marks": 1}]'::jsonb, 'Glycolysis needs NAD to accept hydrogen in its oxidation step [1]; in anaerobic conditions pyruvate accepts the hydrogen from reduced NAD, forming lactate [1]; this regenerates (oxidises) NAD so glycolysis can continue producing 2 ATP per glucose [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0a5fa622-3d29-5fc5-973f-fbb3018dc1e9', '083b2d69-0161-5797-b3f8-177e0f8920e5', 20);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('771da326-e7d5-5187-a6b8-d7012dcdc451', 'short', 'Compare anaerobic respiration in humans and in yeast.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('771da326-e7d5-5187-a6b8-d7012dcdc451', 'Both use glycolysis to produce pyruvate and a net 2 ATP, regenerating NAD [1]; humans convert pyruvate to lactate, while yeast converts it to ethanol [1]; yeast also releases CO₂, humans do not [1].', 'Both use glycolysis to produce pyruvate and a net 2 ATP, regenerating NAD [1]; humans convert pyruvate to lactate, while yeast converts it to ethanol [1]; yeast also releases CO₂, humans do not [1].', '[{"text": "Marking point 1", "any": ["glycolysis", "same pathway"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["ethanol"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["co2"], "all": [], "marks": 1}]'::jsonb, 'Both use glycolysis to produce pyruvate and a net 2 ATP, regenerating NAD [1]; humans convert pyruvate to lactate, while yeast converts it to ethanol [1]; yeast also releases CO₂, humans do not [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0a5fa622-3d29-5fc5-973f-fbb3018dc1e9', '771da326-e7d5-5187-a6b8-d7012dcdc451', 21);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('40d5d031-9774-539b-89e0-0c88b564807a', 'short', 'Suggest why bread dough rises faster in a warm place than in a cold one.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('40d5d031-9774-539b-89e0-0c88b564807a', 'Higher temperature increases enzyme activity, so yeast respires faster [1]; more CO₂ is produced per minute, so the dough rises faster [1].', 'Higher temperature increases enzyme activity, so yeast respires faster [1]; more CO₂ is produced per minute, so the dough rises faster [1].', '[{"text": "Marking point 1", "any": ["enzyme", "faster respiration", "rate of respiration", "respire faster"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["carbon dioxide", "co2", "gas"], "all": [], "marks": 1}]'::jsonb, 'Higher temperature increases enzyme activity, so yeast respires faster [1]; more CO₂ is produced per minute, so the dough rises faster [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0a5fa622-3d29-5fc5-973f-fbb3018dc1e9', '40d5d031-9774-539b-89e0-0c88b564807a', 22);
